#mg-sonatic-family.sf-model{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-width:0;min-height:136px;width:100%;padding:16px 9px;border:1.5px solid var(--line);border-radius:13px;background:#fff;color:var(--ink);text-align:center;transition:.2s}

#mg-sonatic-family.sf-model[aria-pressed=true]{border:2px solid var(--green);background:var(--pale)}

#mg-sonatic-family.sf-model strong{font-size:16px;font-weight:850}

#mg-sonatic-family.sf-selected{margin-top:12px;padding:17px 19px;border:1px solid var(--line);border-radius:12px;background:var(--soft)}

#mg-sonatic-family.sf-selected strong{display:block;margin-bottom:5px;font-size:16px}

/* CARRITO */

#mg-sonatic-family.sf-add{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:55px;padding:13px 18px;border:0;border-radius:10px;background:var(--green);color:#fff;font-size:14px;font-weight:850;transition:background.2s}

#mg-sonatic-family.sf-add svg{width:19px;height:19px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}

#mg-sonatic-family.sf-status.success{color:var(--hover)}

/* PROBADOR */

#mg-sonatic-family.sf-toggle{display:flex;align-items:center;gap:12px;width:100%;padding:16px;border:1px solid #d7e7da;border-radius:13px;background:#fff;color:var(--ink);text-align:left}

#mg-sonatic-family.sf-toggle-copy strong{display:block;font-size:15px}

#mg-sonatic-family.sf-toggle-copy small{display:block;margin-top:3px;color:var(--muted);font-size:12px}

#mg-sonatic-family.sf-chevron{width:18px;height:18px;fill:none;stroke:var(--hover);stroke-width:2;transition:transform.2s}

#mg-sonatic-family.sf-toggle[aria-expanded=true].sf-chevron{transform:rotate(180deg)}

#mg-sonatic-family.sf-probe-body{margin-top:11px;padding:18px;border:1px solid var(--line);border-radius:13px;background:#fff}

#mg-sonatic-family.sf-options.models,

#mg-sonatic-family.sf-options.scenes{grid-template-columns:repeat(3,minmax(0,1fr))}

#mg-sonatic-family.sf-options.levels{grid-template-columns:repeat(auto-fit,minmax(75px,1fr))}

#mg-sonatic-family.sf-opt{min-height:46px;padding:9px 5px;border:1px solid var(--line);border-radius:9px;background:var(--soft);color:var(--ink);font-size:12px;font-weight:750;text-align:center}

#mg-sonatic-family.sf-opt[aria-pressed=true]{border:1.5px solid var(--green);background:var(--pale);color:var(--hover)}

#mg-sonatic-family.sf-player{padding:20px 14px;border:1px solid var(--line);border-radius:12px;background:var(--soft);text-align:center}

#mg-sonatic-family.sf-audio-label{font-size:14px;font-weight:800}

#mg-sonatic-family.sf-wave{display:flex;align-items:center;justify-content:center;gap:3px;height:65px;margin:12px auto}

#mg-sonatic-family.sf-play{display:block;width:100%;max-width:310px;margin:auto;padding:13px;border:0;border-radius:9px;background:var(--ink);color:#fff;font-size:13px;font-weight:800}

#mg-sonatic-family.sf-audio-status{margin-top:10px;color:var(--muted);font-size:12px}

#mg-sonatic-family.sf-disclaimer{margin-top:15px;color:var(--muted);font-size:11px;line-height:1.65}

@keyframes sfFamilyWave{0%,100%{transform:scaleY(.4)}50%{transform:scaleY(1)}}

#mg-sonatic-family.sf-wave--playing i{animation:sfFamilyWave.8s ease-in-out infinite alternate}

/* IMAGEN EN LA DESCRIPCIÓN */

#mg-sonatic-family.sf-emotion p{max-width:570px;margin:14px auto 0}

#mg-sonatic-family.sf-emotion img{display:block;width:100%;max-width:650px;height:auto;margin:23px auto 0;border-radius:13px}

/* COMPARATIVA */

#mg-sonatic-family.sf-compare{padding:40px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--soft)}

#mg-sonatic-family.sf-compare-list{display:grid;gap:9px;margin-top:20px}

#mg-sonatic-family.sf-compare-item{display:flex;align-items:center;gap:13px;padding:15px;border:1px solid var(--line);border-radius:11px;background:#fff}

#mg-sonatic-family.sf-compare-item strong{display:block;font-size:15px;font-weight:800}

#mg-sonatic-family.sf-compare-item p{margin-top:3px;color:var(--muted);font-size:12px}

/* CIERRE */

#mg-sonatic-family.sf-ending h2{font-size:clamp(28px,4.2vw,39px);font-weight:850}

#mg-sonatic-family.sf-back{padding:12px 25px;border:1px solid #bfe4ca;border-radius:9px;background:var(--pale);color:var(--hover);font-size:13px;font-weight:800}

/* NOTIFICACIÓN */

#mg-sonatic-family.sf-toast{position:fixed;right:18px;bottom:20px;z-index:100010;width:min(380px,calc(100vw - 36px));padding:16px;border:1px solid #bce4c6;border-radius:13px;background:#fff;box-shadow:0 10px 35px #0002}

#mg-sonatic-family.sf-toast-inner{display:flex;gap:12px;align-items:center}

#mg-sonatic-family.sf-toast-check{display:flex;align-items:center;justify-content:center;width:34px;height:34px;flex-shrink:0;border-radius:50%;background:var(--pale);color:var(--hover)}

#mg-sonatic-family.sf-toast strong{font-size:14px}

/* MINICARRITO */

#mg-sonatic-family.sf-drawer{position:fixed;top:0;right:0;bottom:0;z-index:100012;width:min(420px,100vw);padding:23px;overflow-y:auto;background:#fff;box-shadow:-10px 0 35px #0002}

#mg-sonatic-family.sf-drawer-head{display:flex;align-items:center;justify-content:space-between;gap:10px}

#mg-sonatic-family.sf-cart-line{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}

#mg-sonatic-family.sf-cart-link{display:block;margin-top:20px;padding:14px;border-radius:9px;background:var(--green);color:#fff!important;font-weight:800;text-align:center;text-decoration:none}

#mg-sonatic-family.sf-model strong{font-size:14px}

#mg-sonatic-family.sf-model small{font-size:10px}

